INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (312, 'Chinese Money Plant', 'chinese-money-plant', 1, 101, 490.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Indoor Plants', 'Plants']::text[], FALSE, FALSE, FALSE, 'The Chinese Money Plant, scientifically known as Pilea peperomioides, is a popular and distinctive houseplant valued for its round, coin-shaped leaves and easy care requirements.…', 'The Chinese Money Plant, scientifically known as Pilea peperomioides, is a popular and distinctive houseplant valued for its round, coin-shaped leaves and easy care requirements. Here are some key details about the Chinese Money Plant:

Appearance: The Chinese Money Plant features round, succulent-like leaves that grow on long, slender stems. The leaves are glossy and typically have a bright green color, with a unique, pancake-like shape that resembles coins stacked on top of each other.

Origin: Native to the southwestern provinces of China, the Chinese Money Plant has gained popularity worldwide as a decorative houseplant.

Cultivation: Chinese Money Plants are relatively easy to care for and thrive in bright, indirect light. They prefer well-draining soil and moderate watering, allowing the soil to dry out slightly between waterings. They can also tolerate lower light conditions but may grow more slowly.

Propagation: Chinese Money Plants can be propagated easily through stem or leaf cuttings. Simply snip off a healthy stem or leaf and place it in water or soil to root. Once roots have formed, the cutting can be potted up into its own container.

Maintenance: Chinese Money Plants are generally low-maintenance plants. They benefit from occasional pruning to remove dead or yellowing leaves and encourage bushier growth. Regularly rotating the plant can also help ensure even growth on all sides.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:38:39.535Z', NULL, NULL, NULL, NULL, NULL, 'The Chinese Money Plant, scientifically known as Pilea peperomioides, is a popular and distinctive houseplant valued for its round, coin-shaped leaves and eas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Chinese Money Plant');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (313, 'Diffenbachia', 'diffenbachia', 1, 101, 430.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Indoor Plants', 'Plants']::text[], FALSE, FALSE, FALSE, 'Dieffenbachia, also known as Dumb Cane, is a popular and ornamental houseplant valued for its large, lush foliage and easy care requirements. Here are some key details about…', 'Dieffenbachia, also known as Dumb Cane, is a popular and ornamental houseplant valued for its large, lush foliage and easy care requirements. Here are some key details about Dieffenbachia:

Appearance: Dieffenbachia plants feature large, broad leaves that are typically variegated with patterns of white, cream, or yellow. The leaves can grow quite large, and their shape may vary depending on the species or cultivar.

Origin: Native to tropical regions of Central and South America, Dieffenbachia is commonly cultivated as a houseplant in temperate climates around the world.

Cultivation: Dieffenbachia thrives in indoor environments with bright, indirect light. It prefers well-draining soil and regular watering, allowing the soil to dry out slightly between waterings. Avoid overwatering, as it can lead to root rot.

Toxicity: It''s important to note that Dieffenbachia plants are toxic if ingested. The sap of the plant contains calcium oxalate crystals, which can cause irritation and swelling of the mouth and throat if consumed. Keep the plant out of reach of children and pets, and wash your hands after handling it.

Propagation: Dieffenbachia can be propagated through stem cuttings. Simply cut a section of stem with at least one leaf node, and place it in water or moist soil until roots develop. Once rooted, the cutting can be potted up into its own container.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:38:39.535Z', NULL, NULL, NULL, NULL, NULL, 'Dieffenbachia, also known as Dumb Cane, is a popular and ornamental houseplant valued for its large, lush foliage and easy care requirements. Here are some ke', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diffenbachia');
