INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (329, 'Wandering Jew Pink', 'wandering-jew-pink', 1, 102, 290.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], FALSE, FALSE, FALSE, 'Trailing Tradescantia in pink, silver and deep purple — fast, forgiving and easy to propagate.', 'A trailing Tradescantia striped in pink, silver and deep purple. It grows quickly in bright indirect light — the more light, the stronger the pink — and any piece you pinch off will root in water within a week. Trim it back when it goes leggy and it returns fuller.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Wandering Jew Pink');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (330, 'Sansaveria', 'sansaveria', 1, 102, 240.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], FALSE, FALSE, FALSE, 'The snake plant: upright, architectural and nearly impossible to kill.', 'The snake plant, with stiff upright leaves banded in green and silver. It tolerates low light, irregular watering and long absences, which is why it ends up in offices and stairwells. The only real way to harm it is to water it too often — let the soil dry completely first.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sansaveria');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (331, 'Donkey Tail', 'donkey-tail', 1, 102, 310.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], FALSE, FALSE, FALSE, 'A heavy trailing sedum packed with plump blue-green beads.', 'Sedum morganianum, whose stems thicken into ropes of plump blue-green beads and can hang half a metre or more. Hang it somewhere it will not be knocked, as the beads detach easily — though each one that falls will root itself into a new plant. Bright light, rare watering.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Donkey Tail');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (332, 'String of Hearts', 'string-of-hearts', 1, 102, 320.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], TRUE, TRUE, TRUE, 'Fine trailing vines strung with marbled heart-shaped leaves.', 'Ceropegia woodii sends down fine purple vines strung with small marbled hearts. It is happiest in bright indirect light with a thorough soak once the soil is dry, and it will trail for metres given a high shelf. The tubers that form along the stems can be pressed into soil to start another plant.', '', NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'String of Hearts');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (333, 'String of Pearls', 'string-of-pearls', 1, 102, 310.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], FALSE, FALSE, FALSE, 'A cascade of round green beads on fine trailing stems.', 'A cascade of round green beads on fine stems, one of the most recognisable trailing succulents there is. It needs more light than most people give it and far less water — soak it, then leave it until the beads just begin to soften. Shallow, wide pots suit its shallow roots.', NULL, NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'String of Pearls');
INSERT INTO "products" ("id", "name", "slug", "category_id", "subcategory_id", "price", "discount_price", "sku", "stock", "avg_rating", "review_count", "tags", "is_featured", "is_new", "is_bestseller", "short_description", "description", "care_instructions", "craftsmanship_story", "created_at", "updated_at", "shipping_weight_kg", "package_length_cm", "package_width_cm", "package_height_cm", "seo_title", "seo_description", "seo_keywords", "canonical_url", "meta_robots", "og_title", "og_description", "og_image", "twitter_title", "twitter_description", "twitter_image", "image_alt_text") VALUES (334, 'String of Drops', 'string-of-drops', 1, 102, 320.00, NULL, NULL, 10000, 5.00, 0, ARRAY['Plants', 'Seculants']::text[], TRUE, TRUE, TRUE, 'Tear-shaped beads on trailing stems, each with a translucent window.', 'Senecio herreianus, whose beads are tear-shaped rather than round, each carrying a translucent stripe that lets light reach the leaf interior. Treat it as you would String of Pearls: bright light, fast-draining soil, and water only once it has fully dried.', '', NULL, '2026-08-17T15:47:40.040Z', '2026-08-20T11:39:39.170Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'String of Drops');
