-- site_content (4 rows)
DELETE FROM "site_content";
INSERT INTO "site_content" ("key", "content", "updated_at") VALUES ('about_page', '{"pillars":[{"copy":"Every variegated specimen is nurtured in our temperature-controlled Coorg nursery until its fenestrations mature and its aerial root architecture is established.","title":"Eighteen months of care"},{"copy":"Our arts collection is cast by Bastar bell metal families in Chhattisgarh using the lost-wax Dhokra method, and thrown by ceramic artists in Jaipur.","title":"Four thousand years of craft"},{"copy":"White-glove, temperature-controlled transport with a seven-day health guarantee. If a plant does not settle, we replace it.","title":"Delivered as living things"}],"ctaTitle":"Begin your collection","heroImage":"https://images.unsplash.com/photo-1470058869958-2a77ade41c02?auto=format&fit=crop&w=2000&q=80","heroIntro":"ORIVIDA exists for people who treat living things as heirlooms — rare botanicals raised slowly, and craft made by hands that learned it from the generation before.","heroTitle":"Our passion,","craftImage":"https://orvida.onrender.com/uploads/images-1787119392266-415303952.jpeg","heroAccent":"ur luxury","milestones":[{"label":"Botanicals hand-nurtured","value":"15,000+"},{"label":"Artisan families supported","value":"120+"},{"label":"Average nursery maturation","value":"18 mo"}],"ctaSubtitle":"Rare specimens, artisan planters and heritage craft — curated and delivered with care.","heroEyebrow":"Our story","craftEyebrow":"The Bastar workshops","craftHeading":"Craft that predates the wheel it is cast on","craftParagraph1":"Dhokra casting has been practised in central India for roughly four thousand years. A beeswax model is sheathed in clay, fired until the wax runs out, and the void filled with molten bell metal. The mould is broken to release the piece, so no two are ever identical.","craftParagraph2":"We commission directly from the families who hold this knowledge, and every piece ships with a signed lineage certificate naming the artisan who made it."}'::jsonb, '2026-08-19T06:03:21.822Z');
INSERT INTO "site_content" ("key", "content", "updated_at") VALUES ('announcements', '{"messages":["Complimentary shipping on orders above ₹1,999","Any 4 plants at ₹999 — limited botanical offer","7-day plant health guarantee on every specimen"]}'::jsonb, '2026-08-19T07:55:04.386Z');
INSERT INTO "site_content" ("key", "content", "updated_at") VALUES ('home_brand_story', '{"image":"https://orvida.onrender.com/uploads/images-1787119376817-534737070.jpeg","eyebrow":"Ancestral craft, botanical mastery","heading":"Where botanical passion meets","buttonText":"Read our story","paragraph1":"At ORIVIDA we believe true luxury is organic, enduring and deeply connected to nature. Our botanists hand-nurture every variegated Monstera and Sansevieria for more than eighteen months in organic soil blends before it reaches your home.","paragraph2":"Our arts collection honours Chhattisgarh''s four-thousand-year-old Bastar bell metal tradition and Jaipur''s ceramic artists — planters and sculptures made to be inherited.","headingAccent":"uncompromising luxury"}'::jsonb, '2026-08-19T06:02:59.282Z');
INSERT INTO "site_content" ("key", "content", "updated_at") VALUES ('seo_settings', '{"siteName":"ORIVIDA","metaTitle":"ORIVIDA — Our Passion, UR Luxury | Premium Plants, Gifting & Décor","defaultRobots":"index, follow","titleTemplate":"%title% | %siteName%","metaDescription":"ORIVIDA offers handcrafted botanical luxury, rare indoor plants, bespoke plant hampers, balcony makeovers, and authentic bell metal & ceramic decor — delivered across India.","twitterCardType":"summary_large_image","organizationLogo":"/logo.png","organizationName":"ORIVIDA","organizationEmail":"support@orvida.com","organizationPhone":"+91 70957 56434","organizationAddress":"3-4-610/1, Narayanguda, Hyderabad, Telangana 500029, India","organizationDescription":"Hand-nurtured rare botanicals, bespoke plant hampers and heritage Bastar bell metal craft, delivered across India."}'::jsonb, '2026-08-21T10:51:38.583Z');

